update projets set intitule = 'Packages i-Services', description = 'Proposer des packages adaptés aux besoins des établissements pour encourager l’adoption simultanée de plusieurs services et ainsi maximiser l’impact des solutions déployées.' where id = 'PRJ103';
update projets set intitule = 'Optimiser la communication et la visibilité des solutions complémentaires', description = 'Structurer des campagnes de communication ciblées multicanaux pour informer et convaincre les adhérents des bénéfices des nouvelles offres.' where id = 'PRJ104';
update projets set intitule = 'Assistants IA pour les demandes courantes', description = 'Déployer des chatbots capables de répondre instantanément aux questions fréquentes et de rediriger les demandes complexes vers le support humain.' where id = 'PRJ105';
update projets set intitule = 'Moderniser notre outil de support ITSM', description = 'Adopter une solution ITSM moderne et intuitive, adaptée à nos besoins de pilotage, d’automatisation et de qualité de service.' where id = 'PRJ106';
update projets set intitule = 'Optimiser la base de connaissances et les ressources d’auto-assistance', description = 'Organiser une base de connaissances claire, évolutive et bien indexée, enrichie de contenus pédagogiques (guides, FAQ, tutoriels) pour renforcer l’autonomie des utilisateurs.' where id = 'PRJ107';
update projets set intitule = 'Renforcer l’engagement par l’ownership', description = 'Mettre en place une culture de responsabilité individuelle sur chaque ticket, où chaque collaborateur est pleinement engagé dans la résolution, de bout en bout, pour valoriser l’implication et améliorer l’expérience utilisateur.' where id = 'PRJ108';
update projets set intitule = 'Développer les carrières du support', description = 'Mettre en place une filière métier structurée avec des niveaux d’expertise, des parcours d’évolution clairs et des passerelles vers d’autres fonctions, pour valoriser les compétences et fidéliser les talents du support' where id = 'PRJ109';
update projets set intitule = 'Structurer la gestion des priorités avec un répartiteur', description = 'Généraliser le rôle de répartiteur pour assurer une distribution efficace des tickets, en fonction de leur urgence, de leur complexité et des compétences disponibles, afin d’optimiser les délais de traitement.' where id = 'PRJ110';
update projets set intitule = 'Repenser l’expérience de démarrage', description = 'Standardiser le processus d’onboarding des établissements et définir un cadre commun à tous les projets pour fiabiliser les démarrages.' where id = 'PRJ111';
update projets set intitule = 'Penser un parcours adapté aux petites structures', description = 'Concevoir un processus de démarrage simplifié et allégé, pensé pour les établissements de petite taille ou à ressources limitées, afin de garantir un déploiement efficace sans surcharger leurs équipes.' where id = 'PRJ112';
update projets set intitule = 'Empowerment Chef de Projet', description = 'Redonner du pouvoir d’action terrain aux chefs de projet en renforçant leur rôle, leur capacité de décision et leur légitimité pour sécuriser l’exécution et cadrer les projets efficacement.' where id = 'PRJ113';
update projets set intitule = 'Réseau Ambassadeurs', description = 'Mobiliser des utilisateurs expérimentés pour accompagner les nouveaux établissements : partager leurs pratiques, rassurer les équipes et faciliter l’appropriation terrain.' where id = 'PRJ114';
update projets set intitule = 'Kit de conduite du changement CPAGE', description = 'Création d’un kit complet et modulaire (supports, vidéos, témoignages, guides pratiques) destiné aux établissements pour faciliter la transition organisationnelle et l’adhésion des utilisateurs.' where id = 'PRJ115';
update projets set intitule = 'Garantie Activité Démarrage', description = 'Suivi rapproché des nouveaux adhérents sur leurs fonctions critiques (facturation, paie, trésorerie), avec des points de contrôle réguliers pour détecter les blocages et sécuriser leur activité dès les premières semaines.' where id = 'PRJ116';
update projets set intitule = 'Collaborations institutionnelles', description = 'Structurer et activer des partenariats avec les institutions clés (ANAP, ARS, etc.) afin de partager notre expertise et contribuer activement aux orientations nationales du numérique en santé.' where id = 'PRJ117';
update projets set intitule = 'Refonte du site web institutionnel', description = 'Un site clair, moderne, centré sur nos expertises, nos solutions et notre rôle stratégique. Intégration d’un espace “Insight CPAGE” dédié à nos prises de position sectorielles.' where id = 'PRJ118';
update projets set intitule = 'Certification de notre démarche RSE', description = 'Engager une démarche de certification RSE reconnue afin de crédibiliser nos engagements et renforcer notre image d’acteur responsable.' where id = 'PRJ119';
update projets set intitule = 'Structurer une stratégie de communication renforcée sur l’expertise CPAGE.', description = 'Développer un plan de communication multi-canal mettant en avant les succès, l’innovation et l’impact des solutions CPAGE sur la performance hospitalière.' where id = 'PRJ120';
update projets set intitule = 'Campagne de sensibilisation auprès des décideurs hospitaliers', description = 'Créer des supports ciblés (livres blancs, études de cas, webinars) pour démontrer la valeur ajoutée des solutions CPAGE et influencer les choix stratégiques des établissements.' where id = 'PRJ121';
update projets set intitule = 'Mobiliser nos adhérents comme ambassadeurs', description = 'Valoriser l’engagement de nos utilisateurs et les transformer en ambassadeurs de la marque et des produits CPAGE.' where id = 'PRJ122';
update projets set intitule = 'Structuration opérationnelle de l’Alliance SIH', description = 'Formaliser les mécanismes de gouvernance, clarifier les engagements croisés, et mettre en place les outils de pilotage stratégique.' where id = 'PRJ123';
update projets set intitule = 'Lancement de démonstrateurs communs CPAGE / Alliance SIH', description = 'Déployer un ou deux projets pilotes partagés, à forte valeur ajoutée pour les établissements.' where id = 'PRJ124';
update projets set intitule = 'Développement d’une stratégie industrielle conjointe', description = 'S’accorder avec nos partenaires sur les briques logicielles à mutualiser, et définir une méthode progressive pour les développer et les généraliser d’ici 2030.' where id = 'PRJ125';
update projets set intitule = 'Valorisation institutionnelle et politique de l’alliance', description = 'Porter ensemble des messages forts auprès des décideurs publics et s’inscrire dans les appels à projets structurants.' where id = 'PRJ126';
update projets set intitule = 'Charte d’alliance éthique en santé numérique', description = 'Élaborer et promouvoir une charte commune garantissant l’ouverture, la réversibilité, la transparence et la souveraineté des solutions développées ensemble.' where id = 'PRJ127';
update projets set intitule = 'Influence institutionnelle', description = 'Formaliser des collaborations d’influence avec les acteurs institutionnels, au-delà de l’Alliance SIH.' where id = 'PRJ128';
update projets set intitule = 'Cartographier les sources de financement et opportunités', description = 'Création d’un référentiel partagé des appels à projets, régionaux, nationaux, européens, pertinents pour CPAGE. Mise en place d’une veille active, avec un interlocuteur identifié par pôle.' where id = 'PRJ129';
update projets set intitule = 'Lancer un programme "Co- financements Adhérents"', description = 'Créer un dispositif d’appui aux établissements pour monter des dossiers de financement intégrant des briques CPAGE. Ce programme inclura : veille ciblée, kits de candidature, accompagnement méthodologique, et partenariat avec les ARS ou régions.' where id = 'PRJ130';
update projets set intitule = 'Tester un modèle de facturation à la performance', description = 'Lancer une expérimentation sur un module ou un service, avec une part variable indexée sur les gains réalisés ou l’usage réel. Objectif : en tirer des enseignements sur l’acceptabilité et la viabilité du modèle.' where id = 'PRJ131';
update projets set intitule = 'Structurer une fonction « financement & innovation »', description = 'Mise en place d’un binôme DAF / Communication & Marketing pour instruire les réponses aux appels à projets, accompagner les pôles.' where id = 'PRJ132';
update projets set intitule = 'Valoriser nos actifs sous-exploités', description = 'Identifier des briques technologiques, modules ou services ayant un potentiel de monétisation interne ou externe, notamment dans le domaine de la donnée ou de l’IA.' where id = 'PRJ133';
update projets set intitule = 'Score d’usage des i-services', description = 'Définir et déployer un indicateur consolidé mesurant l’usage réel, dont la fréquence d’utilisation et les résultats obtenus pour permettre une lecture consolidée de la valeur perçue.' where id = 'PRJ134';
update projets set intitule = 'Initiative “Trophées de l’Usage”', description = 'Créer un dispositif annuel de récompense des établissements les plus engagés dans l’usage des i-services, sur la base d’indicateurs d’impact et de témoignages terrain.' where id = 'PRJ135';
update projets set intitule = 'Optimiser l’usage GED en environnement GHT', description = 'Accompagner les GHT déjà équipés dans l’activation complète des fonctionnalités GED et la montée en maturité de l’usage.' where id = 'PRJ136';
update projets set intitule = 'CPAGE Success Management', description = 'Déployer une approche structurée pour maximiser la valeur d’usage et la satisfaction des adhérents sur les i- services.' where id = 'PRJ137';
update projets set intitule = 'Engager les utilisateurs dans l''usage', description = 'Déployer une stratégie structurée autour de parcours d’onboarding personnalisés, de contenus éducatifs intégrés dans les i- services (guides, tutoriels, notifications, formations) et de communications proactives.' where id = 'PRJ138';